<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const org='DEMO-APIM',data=ref({apis:[],apps:[],subscriptions:[],health:{}}),busy=ref(false),error=ref('');async function load(){try{data.value=await request('/api/apim/dashboard?organizationCode='+org)}catch(e){error.value=e.message}}async function scenario(){busy.value=true;error.value='';try{const x=Date.now(),api=await request('/api/apim/apis',{method:'POST',body:JSON.stringify({organizationCode:org,apiCode:'CUSTOMER-'+x,apiVersion:'v1',name:'客户主数据查询',basePath:'/customers',owner:'集成平台主管',authType:'JWT',rateLimitPerMinute:2000})}),app=await request('/api/apim/apps',{method:'POST',body:JSON.stringify({organizationCode:org,appCode:'CRM-'+x,name:'CRM消费应用',owner:'应用负责人'})});await request(`/api/apim/apis/${api.id}/submit`,{method:'POST'});await request(`/api/admin/apim/apis/${api.id}/publish`,{method:'POST'});const sub=await request('/api/apim/subscriptions',{method:'POST',body:JSON.stringify({apiId:api.id,appId:app.id,environment:'PROD',dailyQuota:500000})});await request(`/api/admin/apim/subscriptions/${sub.id}/approve`,{method:'POST'});await request(`/api/apim/apis/${api.id}/metrics`,{method:'POST',body:JSON.stringify({windowStart:new Date().toISOString().slice(0,19),calls:18000,errors:7,p95LatencyMs:320})});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(load)</script>
<template><section class="dw-head"><div><span>API OPERATIONS</span><h3>API生命周期与消费治理</h3><p>统一查看发布版本、消费应用、订阅配额及运行质量。</p></div><button @click="scenario" :disabled="busy">{{busy?'正在执行…':'创建发布与订阅场景'}}</button></section><p v-if="error" class="err">{{error}}（审批需要管理员账号）</p><section class="metrics"><article><span>API资产</span><b>{{data.apis.length}}</b></article><article><span>消费应用</span><b>{{data.apps.length}}</b></article><article><span>已批订阅</span><b>{{data.subscriptions.filter(s=>s.status==='APPROVED').length}}</b></article><article><span>调用成功率</span><b>{{data.health.successRate||100}}%</b></article></section><section class="panel"><h4>API目录与运行策略</h4><table><tr><th>API</th><th>路径</th><th>认证</th><th>限流/分钟</th><th>状态</th></tr><tr v-for="a in data.apis" :key="a.id"><td><b>{{a.apiCode}} {{a.apiVersion}}</b><small>{{a.name}}</small></td><td><code>{{a.basePath}}</code></td><td>{{a.authType}}</td><td>{{a.rateLimitPerMinute}}</td><td><i>{{a.status}}</i></td></tr></table></section></template>
<style scoped>.dw-head{display:flex;justify-content:space-between;align-items:end;background:#193c50;color:#fff;padding:26px 30px;border-radius:14px}.dw-head span{font-size:11px;letter-spacing:.16em;color:#9bc4dc}.dw-head h3{font-size:25px;margin:7px 0}.dw-head p{margin:0;color:#c8dae4}.dw-head button{background:#5cc0b3;border:0;border-radius:8px;padding:12px 18px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metrics article,.panel{background:#fff;border:1px solid #dfe6e7;border-radius:12px;padding:20px}.metrics b{display:block;font-size:29px;margin-top:8px}.metrics span{color:#687980}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #edf0f1}td small{display:block;color:#718087}td i{font-style:normal;color:#16715e}.err{color:#a43b35}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}}</style>
